    def authorize_sender(self, user_id, channel_id):
        member = self.state["members"].get(user_id, {})
        conversation = self.state["conversations"].get(channel_id, {})
        return member.get("status") == "ready" and conversation.get("enabled") is True and user_id in conversation.get("members", [])

    async def prepare_event(self, event):
        source = event.source
        transport = getattr(source, '_transport_adapter_ref', None)
        if (not callable(transport) or transport() is not self.adapter or source.is_bot or
                source.platform.value!='slack' or source.scope_id!=self.team or
                not self.authorize_sender(source.user_id,source.chat_id)):
            return False
        if self.vault_service is not None:
            return await self.vault_service.channel_tasks.admit_event(event)
        return True

    def route(self, source):
        from gateway.profile_routing import ProfileRouteRejected

        if source.scope_id != self.team or source.is_bot or not self.authorize_sender(source.user_id, source.chat_id):
            raise ProfileRouteRejected("slack-workspace-membership")
        if getattr(source, 'isolated_task', None) is not None:
            service = getattr(self, 'vault_service', None)
            if service is None:
                raise ProfileRouteRejected('slack-workspace-task-unavailable')
            try:
                profile = service.channel_tasks.execution_route(source)
            except Exception as error:
                raise ProfileRouteRejected('slack-workspace-task-unauthorized') from error
        else:
            profile = self.state["conversations"][source.chat_id]["profile"]
        home = (self.adapter.gateway_runner._served_profile_homes or {}).get(profile)
        expected = self.home if profile == "default" else self.home / "profiles" / profile
        if home is None or Path(home).resolve() != expected.resolve() or not expected.is_dir():
            raise ProfileRouteRejected("slack-workspace-profile-unavailable")
        return profile

    def authorize_source(self, source):
        from gateway.profile_routing import ProfileRouteRejected

        try:
            return source.profile == self.route(source)
        except ProfileRouteRejected:
            return False
"""Owner-scoped tools for Kernel credential collection and browser fill."""
import json

from .service import binding
from .store import AccessError

TOOLS = ['clanker_authenticate','clanker_request_access','clanker_vault_list','clanker_vault_fill','clanker_vault_enter_code','clanker_personal_fill','clanker_personal_read','clanker_task_update','clanker_api_request']


def execute(name,args,**kwargs):
    try:
        turn = binding(kwargs.get('task_id'))
        service = turn.service
        if name == 'clanker_task_update':
            return json.dumps(service.call(service.public_update(turn, **args)))
        if name in ('clanker_pay', 'clanker_request_payment'):
            raise AccessError('Automated payments are unavailable with Kernel Vault.', 403)
        if name == 'clanker_request_access':
            return json.dumps(service.call(service.request_access(turn, **args)))
        try:
            service.assert_private(turn)
        except AccessError:
            return json.dumps(service.call(service.move_private(turn)))
        kernel = getattr(service, 'kernel_vault', None)
        if kernel is None:
            raise AccessError('Kernel Vault is not activated. No local vault fallback is permitted.', 503)
        managed = getattr(service, 'kernel_auth', None)
        if name in {'clanker_authenticate', 'clanker_vault_fill', 'clanker_vault_enter_code'} and managed is not None:
            return json.dumps(service.call(managed.authenticate(turn, handle=args.get('handle'), origin=args.get('origin'),
                resend_link=args.get('resend_link', False) if name == 'clanker_authenticate' else False)))
        if name == 'clanker_authenticate':
            raise AccessError('Kernel Managed Auth is unavailable.', 503)
        if name == 'clanker_api_request':
            from .api import execute as api_request
            return json.dumps(api_request(turn, **args))
        if name == 'clanker_personal_fill':
            return json.dumps(service.personal.fill(turn, **args))
        if name == 'clanker_personal_read':
            return json.dumps(service.personal.read(turn, **args))
        home = service.private_home(turn.source.scope_id, turn.source.user_id)
        with service.lock_for(home):
            if name == 'clanker_vault_list':
                return json.dumps({'provider': 'kernel',
                    'items': service.delegations.items(turn.source.scope_id, turn.source.user_id),
                    'personal_info': service.personal.store(turn.source.scope_id, turn.source.user_id).summary(),
                    'personal_model_access': service.personal.store(turn.source.scope_id, turn.source.user_id).model_access(),
                    'personal_info_url': service.config['public_url'].rstrip('/') + '/vault',
                    'next': 'Use clanker_authenticate for website sign-in, including saved accounts, passwords, SMS and email verification. Kernel hosts the interactive login and resumes only after its result. Use Kernel Vault fill for ordinary personal details and API handles. Never ask for passwords or codes in chat.'})
            access = service.delegations.resolve(turn, args['handle'])
            service.delegations.check_execution(turn)
            if access.meta.kind != 'login':
                raise AccessError('Browser login and verification require a saved Kernel login.', 403)
            if name == 'clanker_vault_fill':
                return json.dumps(kernel.fill_login(turn, access, fields=args.get('fields')))
            if name != 'clanker_vault_enter_code':
                raise AccessError('This credential operation is unavailable.')
        # enter_code owns its synchronous inspection/fill lock. Collection
        # waits on the gateway loop, whose inspection needs that same lock.
        return json.dumps(kernel.enter_code(turn, access, request_new=args.get('request_new', False)))
    except AccessError as error:
        result = {'success': False, 'error': str(error), 'status': error.status}
        if getattr(error, 'kernel_fill_outcome', None) is not None:
            from .fill_outcome import validate_outcome
            try:
                result['fill_outcome'] = validate_outcome(error.kernel_fill_outcome)
            except Exception:
                pass
        return json.dumps(result)
    except Exception:
        return json.dumps({'success': False, 'error': 'Kernel Vault could not complete this operation. No secret has been returned.'})


